// Read-only export of completed production records; does not create or execute tasks.
import fs from 'node:fs/promises';import path from 'node:path';import {fileURLToPath} from 'node:url';import {digest} from '../server/build/development-session.mjs';
const wb=fileURLToPath(new URL('../',import.meta.url)),control=path.join(wb,'.local/kimi-workbench-control'),root=path.join(wb,'.local/fresh25-b'),out=path.join(wb,'qa/20260925-kimi-workbench');
const binding=JSON.parse(await fs.readFile(path.join(control,'binding.json'),'utf8'));
const ledger=JSON.parse(await fs.readFile(path.join(root,'build-tasks/development-authorizations.json'),'utf8'));
const entries=ledger.entries.filter(e=>e.project_id===binding.project_id);const rows=[];
await fs.mkdir(path.join(out,'evidence'),{recursive:true});
for(const e of entries){if(!e.task_id){rows.push({external_id:e.logical_id.split('20260925-')[1],status:'NOT_STARTED',task_id:null});continue;}
 const dir=path.join(root,'build-tasks',e.task_id),t=JSON.parse(await fs.readFile(path.join(dir,'task.json'),'utf8'));if(t.active_attempt_id){rows.push({external_id:t.source.external_id,task_id:t.task_id,status:'RUNNING'});continue;}
 const d=t.development||{},c=t.candidates?.at(-1);const runs=(d.self_tests||[]).map(r=>({number:r.number,status:r.result?.test_status||r.status,bundle_sha256:r.bundle_sha256,sha256:r.sha256,error:r.result?.error||r.error,coverage:r.coverage,report_path:r.report_path,started_at:r.started_at,finished_at:r.finished_at}));
 const row={external_id:t.source.external_id,title:t.template.title,task_id:t.task_id,status:t.task_status,source:t.source,runtime:t.runtime,validation_mode:t.environment_ref.validation_mode,human_review_status:t.human_review_status,started_at:t.started_at,finished_at:t.finished_at,elapsed_ms:Date.parse(t.finished_at)-Date.parse(t.started_at),harness_starts:d.harness_starts||0,tool_calls:d.tool_calls||0,self_tests:runs,submission:d.submission?{outcome:d.submission.outcome,coverage:d.submission.coverage}:null,independent_runs:c?.trial_runs||[],candidate:c?{sha256:c.sha256,bundle:c.bundle,approval_status:c.approval_status}:null,rejections:d.rejections||[],error:t.error};
 const dest=path.join(out,'evidence',t.source.external_id);await fs.mkdir(dest,{recursive:true});
 if(c?.bundle){if(digest(Buffer.from(JSON.stringify(c.bundle.files)))!==c.bundle.sha256)throw Error('BUNDLE_MANIFEST_CHANGED');if(d.self_tests?.at(-1)?.bundle_sha256!==c.bundle.sha256)throw Error('FINAL_WITHOUT_CURRENT_SELF_TEST');for(const f of c.bundle.files){const bytes=await fs.readFile(path.join(dir,'development/final',f.path));if(digest(bytes)!==f.sha256)throw Error('BUNDLE_CHANGED');await fs.mkdir(path.dirname(path.join(dest,'final',f.path)),{recursive:true});await fs.writeFile(path.join(dest,'final',f.path),bytes);}}
 for(const r of d.self_tests||[]){for(const f of r.files||[]){const bytes=await fs.readFile(path.join(dir,'development',path.dirname(r.candidate_path),f.path));if(digest(bytes)!==f.sha256)throw Error('EXECUTION_BUNDLE_CHANGED');const target=path.join(dest,'execution-'+r.number,f.path);await fs.mkdir(path.dirname(target),{recursive:true});await fs.writeFile(target,bytes);}const loc=path.join(dir,'development',r.report_path||'missing');try{const bytes=await fs.readFile(loc);await fs.writeFile(path.join(dest,`execution-${r.number}-report.json`),bytes);}catch(err){if(err.code!=='ENOENT')throw err;}}
 const registered=[];for(const f of t.files||[]){const b=await fs.readFile(path.join(dir,f.relative_path));if(digest(b)!==f.sha256||b.length!==f.bytes)throw Error('REGISTERED_FILE_CHANGED');registered.push({file_id:f.file_id,path:f.relative_path,sha256:f.sha256,bytes:f.bytes});}
 row.registered_files=registered;
 const events=JSON.parse(await fs.readFile(path.join(dir,'development/harness-events.json'),'utf8'));
 const calls=new Map(events.filter(x=>x.type==='tool_call').map(x=>[x.callId,x]));const failedInputs=new Set();
 row.tool_failures=events.filter(x=>x.type==='tool_result'&&x.status==='error').map(x=>{const c=calls.get(x.callId),message=typeof x.result==='string'?x.result:JSON.stringify(x.result),inputHash=digest(Buffer.from(JSON.stringify(c?.input??null))),key=c?.tool+inputHash;let detail;try{detail=JSON.parse(message.replace(/^Error:\s*/,''));}catch{}
 const code=detail?.code||null,category=code==='DRAFT_NOT_CREATED'?'draft_absent':code==='TOOL_ARGUMENTS_INVALID'?'parameter_error':code==='EXECUTION_NOT_AVAILABLE'?'evidence_unavailable':['COVERAGE_BINDING_INVALID','READY_WITH_UNCOVERED_REQUIREMENT'].includes(code)?'submission_rejection':code&&/POLICY_DENIED|CONTRACT|NOT_ALLOWED/.test(code)?'policy_rejection':/invalid.*argument|invalid.*parameter|validation error|invalid_type/i.test(message)?'parameter_error':c?.tool?.includes('playwright-mcp')?'browser_observation_error':'other_tool_error';const repeated=failedInputs.has(key);failedInputs.add(key);return{tool:c?.tool,code,category,input_sha256:inputHash,repeated_identical_failed_request:repeated,message:message.slice(0,2000),message_truncated:message.length>2000};});
 await fs.writeFile(path.join(dest,'result.json'),JSON.stringify(row,null,2));rows.push(row);
}
for(const file of await fs.readdir(path.join(control,'evidence'))){if(file.endsWith('.png'))await fs.copyFile(path.join(control,'evidence',file),path.join(out,'evidence',file));}
await fs.writeFile(path.join(out,'evidence','summary.json'),JSON.stringify({binding,task_count:entries.length,rows},null,2));
console.log(JSON.stringify({total:rows.length,terminal:rows.filter(r=>!['RUNNING','NOT_STARTED'].includes(r.status)).length,harness_starts:rows.reduce((s,r)=>s+(r.harness_starts||0),0),tool_calls:rows.reduce((s,r)=>s+(r.tool_calls||0),0),self_tests:rows.reduce((s,r)=>s+(r.self_tests?.length||0),0),independent:rows.reduce((s,r)=>s+(r.independent_runs?.length||0),0),rows:rows.map(r=>({case:r.external_id,status:r.status,outcome:r.submission?.outcome}))}));
